import json,sys,re,time
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
from native_browser import call
d=json.load(sys.stdin);j=d['job_id'];code=d['code'];assert j in json.loads((Path('/mnt/c/gecko_main/openclaw/application-queue')/'batch-rows2-100-20261014-approved-ids.json').read_text());assert re.fullmatch('[A-Za-z0-9]{8}',code)
q=Path('/mnt/c/gecko_main/openclaw/application-queue');p=json.loads((q/j/'application-package.json').read_text());e=json.loads((q/j/'submission-result.json').read_text());assert e['outcome']=='verification_pending';target=e['targetId']
s=call(['snapshot','--target-id',target,'--format','ai','--interactive','--compact']);k=next(k for k,v in s['refs'].items() if v['role']=='textbox' and v.get('name')=='Security code');submit=next(k for k,v in s['refs'].items() if v['role']=='button' and v.get('name')=='Submit application');call(['type',k,code,'--slowly','--target-id',target]);call(['click',submit,'--target-id',target]);time.sleep(3)
r=call(['evaluate','--target-id',target,'--fn','() => ({url:location.href,title:document.title,text:document.body.innerText})']);c=r['result'];assert c['url']==p['company_application_url']+'/confirmation' and c['title']=='Thank you for applying';assert 'Your application has been received' in c['text'] or 'We have received your application' in c['text'] or (p['company']=='Later' and 'one of our Talent Acquisition team members will review your application!' in c['text'] and 'The Later Team' in c['text']);(q/j/'confirmation.json').write_text(json.dumps(r,indent=2));e.update(outcome='submitted',confirmation_url=c['url'],confirmation_text=c['text'],timestamp=datetime.now(ZoneInfo('America/Denver')).isoformat());e.pop('blocking_questions',None);e.pop('unanswered_required_questions',None);tmp=q/j/'submission-result.tmp';tmp.write_text(json.dumps(e,indent=2));tmp.replace(q/j/'submission-result.json');print(json.dumps({'job_id':j,'outcome':'submitted','confirmation_url':c['url']}))
